import{_ as t,o as a,c as d,a2 as r}from"./chunks/framework.hwbV7reR.js";const m=JSON.parse('{"title":"Совместимость и изменения контракта","description":"","frontmatter":{},"headers":[],"relativePath":"compatibility.md","filePath":"compatibility.md","lastUpdated":1791695486000}'),o={name:"compatibility.md"};function i(n,e,c,s,l,h){return a(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="совместимость-и-изменения-контракта" tabindex="-1">Совместимость и изменения контракта <a class="header-anchor" href="#совместимость-и-изменения-контракта" aria-label="Permalink to &quot;Совместимость и изменения контракта&quot;">​</a></h1><h2 id="независимые-версии" tabindex="-1">Независимые версии <a class="header-anchor" href="#независимые-версии" aria-label="Permalink to &quot;Независимые версии&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Версия</th><th>Что описывает</th></tr></thead><tbody><tr><td><code>VERSION</code> / версия пакета</td><td>Выпуск программы и механизм обновления</td></tr><tr><td><code>/v1</code> и <code>/internal/v2</code></td><td>HTTP-контракт для доверенного backend</td></tr><tr><td><code>schema_version</code></td><td>Структуру документа запроса/ответа</td></tr><tr><td><code>configuration.version</code></td><td>Формат параметров конкретного VPN-движка</td></tr><tr><td><code>revision</code></td><td>Изменение параметров конкретного подключения</td></tr><tr><td>Версия схемы SQLite</td><td>PRAGMA user_version: 0 — прежний журнал, 1 — текущая версия</td></tr></tbody></table><p>Изменение версии пакета не означает смену HTTP-контракта. Имя протокола в модели не подтверждает поддержку: backend и клиент сверяются с capabilities. Сейчас реализован AmneziaWG; TrustTunnel пока не рекламируется рабочим runtime.</p><h2 id="требования-к-изменениям" tabindex="-1">Требования к изменениям <a class="header-anchor" href="#требования-к-изменениям" aria-label="Permalink to &quot;Требования к изменениям&quot;">​</a></h2><ul><li>Сохранять идентификаторы, смысл повторов, статусы HTTP и машинные коды ошибок.</li><li>Рассматривать новый обязательный параметр, новый enum, изменение значения по умолчанию или формата конфигурации как потенциально несовместимое изменение.</li><li>Даже добавление необязательного поля требует проверки: часть моделей строго отклоняет неизвестные поля. Не считать расширение автоматически безопасным.</li><li>Изменение оболочки ошибок, асинхронный ответ 202 или другая семантика create требуют отдельного контракта и плана перехода потребителей.</li><li>Обновлять реализацию, схемы, примеры и контрактные тесты вместе. Генерация OpenAPI и проверка актуальности уже включены в CI; модели renew/replace/enable/disable уже общие для runtime и OpenAPI. Оставшиеся описания ответов и legacy create/lookup проверяются контрактными тестами.</li></ul><p>Legacy v1, корневые совместимые Python-импорты, CLI и systemd entry points остаются действующими. Новые интеграции используют v2. Удаление старой точки входа требует описанной замены, переходного выпуска и проверки реально используемых потребителей. Фиксированный срок поддержки старых веток пока не объявлен.</p><h2 id="обновление-хранения" tabindex="-1">Обновление хранения <a class="header-anchor" href="#обновление-хранения" aria-label="Permalink to &quot;Обновление хранения&quot;">​</a></h2><p>Схема имеет независимую версию <code>PRAGMA user_version</code>. Первая нумерованная миграция принимает известные прежние структуры и атомарно создаёт недостающие таблицы, заполняет device_id/binding_key прежним external_id и фиксирует версию 1. Данные назначений, операций, запретов и leases сохраняются. Ошибка откатывает и DDL, и версию. Запуск с будущей версией, повреждённой текущей схемой или чужой базой запрещён.</p><table tabindex="0"><thead><tr><th>Входной журнал</th><th>Результат</th></tr></thead><tbody><tr><td>Пустая установка</td><td>Схема 1, без назначений и без автоматически добавленных серверов</td></tr><tr><td>0: исходные assignments без device/protocol/revision/binding</td><td>Добавление полей, сохранение connection_id/remote_id, заполнение стабильных идентификаторов</td></tr><tr><td>0: назначения и switches</td><td>Добавление таблиц leases и реестра, сохранение незавершённой цели</td></tr><tr><td>0: leases/access_cache/retired_bindings</td><td>Сохранение sequence, fencing и denied; добавление реестра</td></tr><tr><td>0: полный реестр предыдущего выпуска</td><td>Сохранение ревизий реестра и назначений, фиксация версии 1</td></tr><tr><td>1: текущая схема</td><td>Проверка структуры; повтор не изменяет данные</td></tr><tr><td>Новее 1 или повреждённая схема</td><td>Отказ до миграции, без автоматического исправления</td></tr></tbody></table><p>Матрица относится к проверенным структурам, а не к любому форку с таким же номером релиза. <code>tests/test_storage_upgrade.py</code> проверяет эти варианты и атомарный отказ.</p><p><code>contracts/storage.json</code> задаёт min_read/max_read/write и попадает в release manifest. CI сверяет его с миграциями; сборщик читает контракт из того же Git-коммита, что и код. Историческое <code>journal_schema: 2</code> в release.json означает поддержку leases и не является номером user_version. Старые релизы без storage допускаются только для добавочного перехода 0→1; проверка lease-aware rollback по-прежнему обязательна.</p><p>Updater проверяет совместимость отката до остановки процесса, репетирует миграцию на копии базы и повторяет репетицию на финальном снимке после остановки всех writers. При ошибке проверки здоровья возвращает код/units, сохраняя актуальный журнал. Если живая схема неожиданно вышла за диапазон предыдущего кода, службы остаются остановленными: автоматического восстановления старой базы нет.</p><p>Откат исполняемого кода возможен только при совместимой схеме данных. Нельзя автоматически восстановить старую SQLite-копию поверх актуального журнала после мутаций на VPN-узлах: база может потерять сведения о уже выданном или отозванном доступе. Восстановление резервной копии — отдельная процедура сверки состояния.</p><h2 id="административная-панель" tabindex="-1">Административная панель <a class="header-anchor" href="#административная-панель" aria-label="Permalink to &quot;Административная панель&quot;">​</a></h2><p><a href="./panel.html">Панель просмотра</a> и <code>/admin/v1/overview</code> работают отдельным процессом на <code>127.0.0.1:8793</code>, со своим ключом. Backend API на 8792 не меняется; <code>/internal/admin/*</code> остаётся недоступным. Панель читает схему журнала 1 и отказывает без миграций, если версия другая. Совместимость панели поставляется с её релизом.</p><p>Управление доступно локальному CLI и панели с <code>--manage</code>; они используют общие команды и проверки. <code>operator.sqlite3</code> — отдельный журнал намерений версии 1, который включён в backup. Основная схема VPN-журнала остаётся версии 1. Старый код не использует аудит; записи после отката автоматически не повторяются. Политики записываются атомарно в settings.json и применяются при новом запуске процесса; текущие операции продолжают с прежней политикой. Панель не переносит биллинг и пользовательскую авторизацию в оркестратор и не создаёт зависимости от админки Undercore.</p><h2 id="перед-добавлением-второго-протокола" tabindex="-1">Перед добавлением второго протокола <a class="header-anchor" href="#перед-добавлением-второго-протокола" aria-label="Permalink to &quot;Перед добавлением второго протокола&quot;">​</a></h2><p>TrustTunnel проходит те же гарантии идентичности, повторов, истечения срока и отзыва, что AmneziaWG. Его транспортные параметры и экспорты определяет адаптер; форматы <code>.conf</code>, <code>.vpn</code> и QR нельзя автоматически приписывать новому протоколу. Потребуются проверка реального API узла, реализация драйвера и поддержка движка в клиенте. Автоматическая межпротокольная миграция — отдельное изменение контракта, не часть текущего переключения между узлами AmneziaWG.</p><h2 id="проверенная-совместимость-с-агентом" tabindex="-1">Проверенная совместимость с агентом <a class="header-anchor" href="#проверенная-совместимость-с-агентом" aria-label="Permalink to &quot;Проверенная совместимость с агентом&quot;">​</a></h2><p>Контрактные тесты запускают закреплённый Amnezia-agent и вариант его HTTP API без атомарного <code>/connection</code>: используется прежний fallback получения состояния и конфигурации. Для leases отдельно требуются control_lease version 1, подтверждение controller/sequence/deadline и прекращение доступа узлом. Отсутствие lease не приравнивается к поддержке безопасного переключения после полного отказа сервера. Эти тесты не заявляют совместимость со всеми версиями стороннего Amnezia API.</p>',21)])])}const b=t(o,[["render",i]]);export{m as __pageData,b as default};
